import XCTest
import Foundation
@testable import ScannerCore

// Golden vectors generated by the C# SpreadsheetReader.ReadXlsx: cloud/golden/xlsx-vectors.json + cloud/golden/xlsx/*.xlsx.

final class XlsxReaderTests: XCTestCase {
    func testXlsxVectorsMatchCSharp() throws {
        let root = try GoldenSupport.load("xlsx-vectors.json")
        let cases = root["cases"]?.arrayValue ?? []
        XCTAssertGreaterThanOrEqual(cases.count, 2, "need the golden xlsx cases")
        for c in cases {
            let file = c["file"]?.stringValue ?? ""
            let url = GoldenSupport.golden(file)
            guard let data = try? Data(contentsOf: url) else { XCTFail("\(file): cannot read \(url.path)"); continue }
            let rows: [SaleworkRow]
            do {
                rows = try SaleworkImport.readRows(fileName: (file as NSString).lastPathComponent, data: data)
            } catch {
                XCTFail("\(file): threw \(error)")
                continue
            }
            var diffs: [String] = []
            GoldenSupport.diffRows(GoldenSupport.rows(c["rows"]), rows, path: "rows", checkOrder: true, into: &diffs)
            if !diffs.isEmpty { XCTFail("\(file): \(diffs.count) difference(s):\n" + diffs.prefix(10).joined(separator: "\n")) }
        }
    }

    func testSaleworkXlsxGoesThroughTheWholePipeline() throws {
        let url = GoldenSupport.golden("xlsx/salework-basic.xlsx")
        guard let data = try? Data(contentsOf: url) else { XCTFail("cannot read \(url.path)"); return }
        let rows = try SaleworkImport.readRows(fileName: "salework-basic.xlsx", data: data)
        let clean = XlsxSpreadsheetReader.dropPersonalColumns(rows)
        XCTAssertFalse(clean.contains { $0.keys.contains("Số điện thoại") })
        XCTAssertEqual(SaleworkImport.orderIds(clean), ["587069307928479483", "ORD-2"])
        // ORD-2 has quantity "2.5": the C# mapper throws FormatException, so must the port.
        XCTAssertThrowsError(try SaleworkImport.prepare(rows: rows, todayYear: 2026))
    }

    func testSerialToText() {
        XCTAssertEqual(XlsxSpreadsheetReader.serialToText(46336.3541666667), "2026-11-10 08:30:00")
        XCTAssertEqual(XlsxSpreadsheetReader.serialToText(46336), "2026-11-10")
        XCTAssertEqual(XlsxSpreadsheetReader.serialToText(46346.5), "2026-11-20 12:00:00")
        XCTAssertEqual(XlsxSpreadsheetReader.serialToText(1), "1899-12-31")
        XCTAssertEqual(XlsxSpreadsheetReader.serialToText(60), "1900-02-28")
        XCTAssertEqual(XlsxSpreadsheetReader.serialToText(0.25), "1899-12-30 06:00:00")
    }

    func testColIndexAndHeaderNames() {
        XCTAssertEqual(XlsxSpreadsheetReader.colIndex("A1"), 0)
        XCTAssertEqual(XlsxSpreadsheetReader.colIndex("Z9"), 25)
        XCTAssertEqual(XlsxSpreadsheetReader.colIndex("AA10"), 26)
        XCTAssertEqual(XlsxSpreadsheetReader.headerNames(["A", " A ", "", "B", "A"]), ["A", "A_1", "__col2", "B", "A_2"])
    }

    func testCsvQuotedCellsAndCrLf() throws {
        let csv = "\u{FEFF}Mã đơn hàng,Trạng thái,Số lượng\r\nA1,\"ĐANG, HOÀN\",1\r\n,,\r\nA2,\"x \"\"y\"\"\",2"
        let rows = try SaleworkImport.readRows(fileName: "x.CSV", data: Data(csv.utf8))
        XCTAssertEqual(rows.count, 2)
        XCTAssertEqual(rows.first?.dictionary, ["Mã đơn hàng": "A1", "Trạng thái": "ĐANG, HOÀN", "Số lượng": "1"])
        XCTAssertEqual(rows.last?.dictionary["Trạng thái"], "x \"y\"")
        XCTAssertEqual(rows.first?.keys, ["Mã đơn hàng", "Trạng thái", "Số lượng"])
    }

    func testSemicolonCsv() throws {
        let csv = "Order ID;Product Name;Quantity\nO1;Shirt;1\n"
        let rows = try XlsxSpreadsheetReader.readCsv(csv)
        XCTAssertEqual(rows.map { $0.dictionary }, [["Order ID": "O1", "Product Name": "Shirt", "Quantity": "1"]])
    }

    func testErrors() {
        XCTAssertThrowsError(try SaleworkImport.readRows(fileName: "a.pdf", data: Data())) { e in
            XCTAssertEqual((e as? SpreadsheetFormatError)?.message, "Định dạng file không hỗ trợ: \".pdf\" (chỉ nhận .xlsx, .csv).")
        }
        XCTAssertThrowsError(try SaleworkImport.readRows(fileName: "a.xlsx", data: Data("not a zip".utf8))) { e in
            XCTAssertEqual((e as? SpreadsheetFormatError)?.message, "Không phải file .xlsx hợp lệ.")
        }
        XCTAssertThrowsError(try XlsxSpreadsheetReader.readCsv("a,b\n1,2\n")) { e in
            XCTAssertEqual((e as? SpreadsheetFormatError)?.notAnOrderTable, true)
        }
        XCTAssertEqual(try XlsxSpreadsheetReader.readCsv(""), [])
    }

    func testStoredZipEntryIsRead() throws {
        // title-rows-second-sheet.xlsx stores sheet2 without compression (method 0) and sheet1 with deflate.
        let url = GoldenSupport.golden("xlsx/title-rows-second-sheet.xlsx")
        guard let data = try? Data(contentsOf: url) else { XCTFail("cannot read \(url.path)"); return }
        let zip = try XlsxZip(data: data)
        XCTAssertNotNil(zip.entry(named: "xl/worksheets/sheet2.xml"))
        if let e = zip.entry(named: "xl/worksheets/sheet2.xml") {
            let text = String(decoding: try zip.read(e), as: UTF8.self)
            XCTAssertTrue(text.contains("<sheetData>"))
        }
        if let e = zip.entry(named: "xl/worksheets/sheet1.xml") {
            let text = String(decoding: try zip.read(e), as: UTF8.self)
            XCTAssertTrue(text.contains("<sheetData>"))
        }
    }
}
